#!/usr/bin/env python3

import csv
import json
from decimal import Decimal, ROUND_HALF_UP


Q = Decimal("0.01")


def d(x) -> Decimal:
    """Parse a CSV scalar into a Decimal."""
    if x is None:
        raise ValueError("Expected value, got None")
    s = str(x).strip()
    if s == "":
        raise ValueError("Expected non-empty value")
    return Decimal(s)


def money(x: Decimal) -> Decimal:
    """Quantize a Decimal to 2dp using half-up rounding."""
    return x.quantize(Q, rounding=ROUND_HALF_UP)


def money_f(x: Decimal) -> float:
    """Quantize to 2dp and convert to float for JSON output."""
    return float(money(x))


def read_ingredient_cost(path: str):
    meds = {}
    with open(path, newline="") as f:
        r = csv.DictReader(f)
        required = {"medication", "price_per_1000_capsules_usd", "blister_card_count"}
        if set(r.fieldnames or []) != required:
            # Be tolerant of column order, strict about presence
            missing = required - set(r.fieldnames or [])
            extra = set(r.fieldnames or []) - required
            if missing or extra:
                raise ValueError(
                    f"ingredient_cost.csv columns mismatch. missing={sorted(missing)} extra={sorted(extra)} got={r.fieldnames}"
                )
        for row in r:
            name = row["medication"].strip()
            if not name:
                raise ValueError("Empty medication name in ingredient_cost.csv")
            if name in meds:
                raise ValueError(f"Duplicate medication in ingredient_cost.csv: {name}")
            meds[name] = {
                "price_per_1000_capsules_usd": d(row["price_per_1000_capsules_usd"]),
                "blister_card_count": int(Decimal(row["blister_card_count"]).to_integral_value(rounding=ROUND_HALF_UP)),
            }
    return meds


def read_card_cost(path: str):
    by_count = {}
    with open(path, newline="") as f:
        r = csv.DictReader(f)
        required = {"blister_card_count", "card_cost_usd"}
        if set(r.fieldnames or []) != required:
            missing = required - set(r.fieldnames or [])
            extra = set(r.fieldnames or []) - required
            if missing or extra:
                raise ValueError(
                    f"card_cost.csv columns mismatch. missing={sorted(missing)} extra={sorted(extra)} got={r.fieldnames}"
                )
        for row in r:
            count = int(Decimal(row["blister_card_count"]).to_integral_value(rounding=ROUND_HALF_UP))
            if count in by_count:
                raise ValueError(f"Duplicate blister_card_count in card_cost.csv: {count}")
            by_count[count] = d(row["card_cost_usd"])
    return by_count


def read_reimbursement(path: str):
    meds = {}
    with open(path, newline="") as f:
        r = csv.DictReader(f)
        required = {"medication", "reimbursement_per_cycle_180_patients_usd"}
        if set(r.fieldnames or []) != required:
            missing = required - set(r.fieldnames or [])
            extra = set(r.fieldnames or []) - required
            if missing or extra:
                raise ValueError(
                    f"reimbursement.csv columns mismatch. missing={sorted(missing)} extra={sorted(extra)} got={r.fieldnames}"
                )
        for row in r:
            name = row["medication"].strip()
            if not name:
                raise ValueError("Empty medication name in reimbursement.csv")
            if name in meds:
                raise ValueError(f"Duplicate medication in reimbursement.csv: {name}")
            meds[name] = {
                "reimbursement_per_cycle_180_patients_usd": d(
                    row["reimbursement_per_cycle_180_patients_usd"]
                )
            }
    return meds


def main():
    ingredient = read_ingredient_cost("/root/ingredient_cost.csv")
    card_cost_by_count = read_card_cost("/root/card_cost.csv")
    reimbursement = read_reimbursement("/root/reimbursement.csv")

    ingredient_meds = set(ingredient.keys())
    reimbursement_meds = set(reimbursement.keys())
    if ingredient_meds != reimbursement_meds:
        missing_in_reimb = sorted(ingredient_meds - reimbursement_meds)
        missing_in_ing = sorted(reimbursement_meds - ingredient_meds)
        raise ValueError(
            "Medication sets do not match across files. "
            f"missing_in_reimbursement={missing_in_reimb} missing_in_ingredient_cost={missing_in_ing}"
        )

    medications_out = []

    total_margin_28 = Decimal("0")
    total_margin_56 = Decimal("0")
    total_diff = Decimal("0")

    # Constants from spec
    patients = Decimal("180")
    caps_per_28day = Decimal("56")
    caps_per_56day = Decimal("112")
    fills_28_per_year = Decimal("12")
    fills_56_per_year = Decimal("6")

    for med in sorted(ingredient_meds):
        price_per_1000 = ingredient[med]["price_per_1000_capsules_usd"]
        blister_card_count = ingredient[med]["blister_card_count"]
        if blister_card_count not in card_cost_by_count:
            raise ValueError(
                f"No card_cost_usd found for blister_card_count={blister_card_count} (medication={med})"
            )
        card_cost = card_cost_by_count[blister_card_count]
        reimb_per_cycle = reimbursement[med]["reimbursement_per_cycle_180_patients_usd"]

        # Drug cost per year (should be identical across models)
        drug_cost_28 = (price_per_1000 / Decimal("1000")) * caps_per_28day * patients * fills_28_per_year
        drug_cost_56 = (price_per_1000 / Decimal("1000")) * caps_per_56day * patients * fills_56_per_year

        # Packaging cost per year (per patient per fill)
        pkg_cost_28 = card_cost * patients * fills_28_per_year
        pkg_cost_56 = card_cost * patients * fills_56_per_year

        # Annual reimbursement
        annual_reimb_28 = reimb_per_cycle * fills_28_per_year
        annual_reimb_56 = reimb_per_cycle * fills_56_per_year

        margin_28 = annual_reimb_28 - drug_cost_28 - pkg_cost_28
        margin_56 = annual_reimb_56 - drug_cost_56 - pkg_cost_56
        diff_56_minus_28 = margin_56 - margin_28

        total_margin_28 += margin_28
        total_margin_56 += margin_56
        total_diff += diff_56_minus_28

        medications_out.append(
            {
                "medication": med,
                "price_per_1000_capsules_usd": money_f(price_per_1000),
                "blister_card_count": blister_card_count,
                "card_cost_usd": money_f(card_cost),
                "reimbursement_per_cycle_180_patients_usd": money_f(reimb_per_cycle),
                "annual_drug_cost_28_day_usd": money_f(drug_cost_28),
                "annual_drug_cost_56_day_usd": money_f(drug_cost_56),
                "annual_packaging_cost_28_day_usd": money_f(pkg_cost_28),
                "annual_packaging_cost_56_day_usd": money_f(pkg_cost_56),
                "annual_reimbursement_28_day_usd": money_f(annual_reimb_28),
                "annual_reimbursement_56_day_usd": money_f(annual_reimb_56),
                "annual_margin_28_day_usd": money_f(margin_28),
                "annual_margin_56_day_usd": money_f(margin_56),
                "margin_difference_56_minus_28_usd": money_f(diff_56_minus_28),
            }
        )

    totals = {
        "total_annual_margin_28_day_usd": money_f(total_margin_28),
        "total_annual_margin_56_day_usd": money_f(total_margin_56),
        "total_annual_margin_difference_56_minus_28_usd": money_f(total_diff),
        "absolute_total_margin_difference_usd": money_f(abs(total_diff)),
    }

    decision = "convert_to_56_day" if abs(total_diff) < Decimal("9000") else "keep_28_day"
    justification = (
        f"Absolute total margin difference is ${money(abs(total_diff))} (threshold: $9000.00); "
        f"therefore decision is '{decision}'."
    )

    out = {
        "medications": medications_out,
        "totals": totals,
        "recommendation": {"decision": decision, "justification": justification},
    }

    with open("/root/syncpack_analysis.json", "w") as f:
        json.dump(out, f, indent=2)
        f.write("\n")

    with open("/root/syncpack_summary.md", "w") as f:
        f.write(f"Total 28-day margin (USD): {totals['total_annual_margin_28_day_usd']:.2f}\n")
        f.write(f"Total 56-day margin (USD): {totals['total_annual_margin_56_day_usd']:.2f}\n")
        f.write(f"Absolute difference (USD): {totals['absolute_total_margin_difference_usd']:.2f}\n")
        f.write(f"Final decision: {decision}\n")


if __name__ == "__main__":
    main()

