        raise ValueError("Expected non-empty value")
    return Decimal(s)


def money(x: Decimal) -> Decimal:
    """Quantize a Decimal to 2dp using half-up rounding."""
    return x.quantize(Q, rounding=ROUND_HALF_UP)


def money_f(x: Decimal) -> float:
    """Quantize to 2dp and convert to float for JSON output."""
    return float(money(x))


def read_ingredient_cost(path: str):
    meds = {}
    with open(path, newline="") as f:
        r = csv.DictReader(f)
        required = {"medication", "price_per_1000_capsules_usd", "blister_card_count"}
        if set(r.fieldnames or []) != required:
            # Be tolerant of column order, strict about presence
            missing = required - set(r.fieldnames or [])
            extra = set(r.fieldnames or []) - required
            if missing or extra:
                raise ValueError(
                    f"ingredient_cost.csv columns mismatch. missing={sorted(missing)} extra={sorted(extra)} got={r.fieldnames}"
                )
        for row in r:
            name = row["medication"].strip()
            if not name:
                raise ValueError("Empty medication name in ingredient_cost.csv")
            if name in meds:
                raise ValueError(f"Duplicate medication in ingredient_cost.csv: {name}")
            meds[name] = {
                "price_per_1000_capsules_usd": d(row["price_per_1000_capsules_usd"]),
                "blister_card_count": int(Decimal(row["blister_card_count"]).to_integral_value(rounding=ROUND_HALF_UP)),
